from math import comb

def lucas_mod2(N,K):
    return int(K >= 0 and K <= N and K & ~N == 0)

for s in range(3,17):
    n=1<<(s-1); j=2*n-2; d=3*n-2; k=n-2
    assert lucas_mod2(j,k)==1
    assert (j+k,2*j-k)==(d-2,d)
    # For d-1, the only possible k is n-1, which is odd.
    assert max(0,2*j-(d-1)) == n-1
    assert min(j,d-1-j) == n-1
    assert lucas_mod2(j,n-1)==0
    if s<=10:
        assert comb(j,k)%2==1
    print(f's={s}: j={j}, d={d}, witness monomial x^{d-2} y^{d}, coefficient odd; obstruction at d-1 vanishes')
# Direct expansion/reduction checks, independently via binomial coefficients.
for s in range(3,11):
    n=1<<(s-1);j=2*n-2;d=3*n-2
    coeff={ (j+k,2*j-k): comb(j,k)%2 for k in range(j+1)}
    surviving={uv:c for uv,c in coeff.items() if c and max(uv)<=d}
    assert surviving == {(d-2,d):1,(d,d-2):1}
    assert not any(c and max(uv)<d for uv,c in coeff.items())
print('Independent direct binomial expansion checks passed s=3,...,10.')

import numpy as np,itertools,math,time
j=6; d=9
parts=[]
for singles in itertools.combinations(range(j),j//2):
 singles=set(singles)
 for choices in itertools.product(range(3),repeat=j):
  a=[]; b=[];checks=[]
  for i,c in enumerate(choices):
   p=[3*i+k for k in range(3) if k!=c]; q=3*i+c
   if i in singles: a+=[q];b+=p;checks.append((0,*p))
   else:a+=p;b+=[q];checks.append((1,*p))
  if 0 in a:parts.append((a,b,checks))
A=np.array([p[0] for p in parts]); B=np.array([p[1] for p in parts]); checks=np.array([p[2] for p in parts]);print('parts',len(parts))
def count(P):
 P=np.column_stack([P,np.ones(3*j)])
 _,_,vh=np.linalg.svd(P[A],full_matrices=True);na=vh[:,-1,:]
 _,_,vh=np.linalg.svd(P[B],full_matrices=True);nb=vh[:,-1,:]
 va=np.einsum('ik,jk->ij',na,P);vb=np.einsum('ik,jk->ij',nb,P)
 valid=np.ones(len(parts),bool)
 for i in range(j):
  c=checks[:,i];v=np.where(c[:,0,None]==0,va,vb)
  valid&=v[np.arange(len(parts)),c[:,1]]*v[np.arange(len(parts)),c[:,2]]<0
 return valid.sum()
rng=np.random.default_rng(2026)
for r in range(12):
 P=rng.normal(size=(18,9));print(r,count(P))
t=np.linspace(-1,1,18);P=np.array([t**k for k in range(1,10)]).T;print('curve',count(P))

